window.CURATED={
 0:{zh:'虽然有过各种问题，但我想，到头来一切还是会回到里伽子身上。',note:'先抓住句尾的「と思う」＝“我想”。它前面的整段都是“我想”的内容。「は」提示话题，出现了两次；「あった」是「ある」的过去形。「けれど」转折后，「すべては里伽子に戻ってゆく」才是这句话的重点。',g:[['あった','ある → あった','ある是“有”；あった是它的过去形，即“有过”。这里的问题是过去发生过的。'],['けれど','〜けれど','“虽然……但是……”。前面承认有问题，后面转向叙述者现在的感受。'],['戻ってゆく','戻る → 戻って＋ゆく','戻る是“回到”；戻って是て形，后接ゆく，表示事情最后仍朝这个方向发展。'],['んだ','〜んだ','のだ的口语形式，带有解释或得出结论的语气。'],['と思う','内容＋と＋思う','と把前面整个判断引用为“想”的内容；思う＝认为、觉得。']]},
 1:{zh:'那年三月，我有生以来第二次踏上了东京的土地。或者说，是到了羽田。我考上了一所私立大学，于是就这样“上京”了。',note:'「その年の三月に」交代时间。「うまれて二度目」是“出生以来第二次”。「というか」修正上一句的表达。「私大」是私立大学的简称。「上京」指来到东京。'},
 2:{zh:'在市政府工作的母亲请了带薪假，陪我一起来了。来自乡下的母子两人，被人潮推挤着上了单轨电车，又换乘了电车。',note:'「市役所づとめの母親」是“在市政府工作的母亲”。「有休をとる」就是请带薪休假。「人波に押されて」中，押される是押す的被动形式。「のりかえた」是换乘了。'},
 3:{zh:'正为那拥挤程度目瞪口呆时，我们在池袋下了车，又换乘了电车。上上下下爬了好多次楼梯，累得够呛。',note:'「あまりの〜ぶり」强调程度：“实在太……”。「唖然としているうちに」是“正目瞪口呆的时候”。「ので」说明原因，「疲れてしまった」带着已经累坏了的感觉。'}
};

// Opening illustration pass: translations checked against the Japanese, not generated captions.
Object.assign(window.CURATED,{
 4:{zh:'我们最后下车的地方，是石神井公园站。'},
 5:{zh:'母亲手拿地图，一下就找到了离车站步行大约十五分钟的“英公寓”。真有她的。'},
 6:{zh:'住在东京的一位远房阿姨——据说是父亲姐姐的丈夫的妹妹——事先听了我们对租金和条件的要求，帮忙找到了这套公寓。'},
 7:{zh:'房龄十三年，连管理费在内每月六万八千日元。勉强还算六万多日元这一档。',note:'「６万円台」是六万至不到七万日元的范围；「ぎりぎり」表示勉强卡在这个范围内，不是“不到六万”。'},
 8:{zh:'据说两年前重新装修过。厨房约两叠大，墙面贴着壁纸；再往里，是约七叠大小、狭长的木地板房间。朝东的窗户是凸窗，多少有点时髦的样子。',note:'「ウナギの寝床」字面是鳗鱼的睡处，用来形容狭长的空间；这里并不是说房间里有一张床。「出窓」是向外凸出的窗户。'},
 9:{zh:'（一个月要六万多日元，却只有这样的房间啊。东京的物价果然高。）'},
 10:{zh:'虽然心里有些吃惊，但也觉得，大概就是这么回事吧。'},
 11:{zh:'提前用快递寄来的被褥袋和几个纸箱，零零散散地放在房间里。母亲手脚麻利地开始打扫，我却只是在一旁没来由地晃来晃去。'},
 12:{zh:'那天，我们住进了护城河附近一座安静的会馆。说是供地方公务员使用的福利设施，外观看起来却相当豪华，简直像家城市酒店。'},
 13:{zh:'母亲觉得，公寓里连浴巾都没有，总让人安不下心，第一晚还是住在设施齐全的地方吧。她的判断果然没错：吃完饭、洗过澡，疲惫就一下子涌了上来。'},
 14:{zh:'透过那扇不能开合的大窗，可以看见远处皇居如森林般茂密的绿意。周围，一串串拖着光尾的汽车尾灯，仿佛浮在空中，闪闪发亮。'},
 15:{zh:'我隔着玻璃望着空中流动的灯光，不禁感动地想：东京的夜晚真美啊。我真心觉得，东京的夜晚很漂亮。'},
 16:{zh:'那灯光像春日海面上漂浮的渔船灯火，充满一种寂寞的美。不断传来的车声，听起来也像海浪。我仿佛触碰到了某种令人怀念的东西，久久地站在窗边，望着外面。'},
 17:{zh:'初到东京的第一夜，就是这样度过的。'},
 18:{zh:'第二天起，我们搬进了“英公寓”，做起了从外地来到东京的母子通常都会做的事。也就是说，为了迎接新学期，拼命地大买特买。'},
 19:{zh:'电饭锅、烤面包机、锅、床，各种东西接连送了进来。我们买来现成的窗帘装好，又开着吸尘器，嗡嗡地打扫。'},
 20:{zh:'母亲每天早晨到车站前的银行，用银行卡取出五万、十万日元。我在旁边看着，心里除了感激还是感激。',note:'「５万10万」指五万、十万日元这样一笔笔取钱，并不是“5010万”。这里体现了母亲为儿子的生活开销不断支出。'},
 21:{zh:'总之，在此前十八年的人生里，'},
 22:{zh:'（啊，原来孩子就是花着父母的钱生活的啊。）'},
 23:{zh:'像这样深切地体会到这一点，我还是头一回。'},
 24:{zh:'我父母都是公务员，家里倒也不算太拮据。不过，我还有个小两岁的弟弟。想到接下来几年两个儿子的教育费用，哪怕离车站要走十五分钟、房子已有十三年，也已经该谢天谢地了。'},
 25:{zh:'“这段时间，真是让您费心了。”'},
 26:{zh:'母亲明天就要回高知了。那天晚上，我在薄薄的木地板上端正跪坐，轻轻低下头向她道谢。'},
 27:{zh:'想起来，这也是我第一次用郑重的敬体语气向父母道谢。',note:'「デスマス体」就是用です、ます结尾的礼貌说法，又称敬体；不是“面具”。这里的郑重语气让道谢显得格外认真。'},
 28:{zh:'“唉，一下子花掉这么多钱，连花钱也会花累呢。”'},
 29:{zh:'母亲的脸上隐约带着疲惫，露出了有些寂寞的微笑。'},
 30:{zh:'短短这几天，七七八八加起来，三十张一万日元的钞票肯定已经花出去了，所以母亲的话里也带着切身的感受。我也“姆哈哈”地干笑了一下。'},
 31:{zh:'母亲环视了一圈房间，'},
 32:{zh:'“东西置办到这个程度，日常生活也就不会有什么不方便了吧。要是想搬到更好的地方，或者买更好的家具，剩下的就自己来吧。玩也好，做什么也好，都随你。不过，每个月给你寄的生活费就是十二万日元。余下的，就靠你自己了。”'},
 33:{zh:'她说话的口气，简直像是在叮嘱刚入职的年轻公务员。'},
 34:{zh:'“嗯。我会打工，也会好好享受生活的。”'},
 35:{zh:'我笑着回答。'},
 366:{zh:'上面这样写着。'}
});

/* BEGIN GENERATED TRANSLATION REVIEW */
// Keep existing grammar explanations; only replace reviewed translations.
for(const [index,zh,translationReview] of [[0,"虽然有过各种问题，但我想，到头来一切还是会回到里伽子身上。",{"revision":"opening-2026-11-04"}],[1,"那年三月，我有生以来第二次踏上了东京的土地。或者说，是到了羽田。我考上了一所私立大学，于是就这样“上京”了。",{"revision":"opening-2026-11-04","note":"「というか」是叙述者随口修正说法：“踏上东京的土地”其实就是到了羽田。原文没有“把青春堂堂正正地挥洒”等扩写。"}],[2,"在市政府工作的母亲请了带薪假，陪我一起来了。来自乡下的母子两人，被人潮推挤着上了单轨电车，又换乘了电车。",{"revision":"opening-2026-11-04"}],[3,"正为那拥挤程度目瞪口呆时，我们在池袋下了车，又换乘了电车。上上下下爬了好多次楼梯，累得够呛。",{"revision":"opening-2026-11-04"}],[4,"我们最后下车的地方，是石神井公园站。",{"revision":"opening-2026-11-04"}],[5,"母亲手拿地图，一下就找到了离车站步行大约十五分钟的“英公寓”。真有她的。",{"revision":"opening-2026-11-04"}],[6,"住在东京的一位远房阿姨——据说是父亲姐姐的丈夫的妹妹——事先听了我们对租金和条件的要求，帮忙找到了这套公寓。",{"revision":"opening-2026-11-04"}],[7,"房龄十三年，连管理费在内每月六万八千日元。勉强还算六万多日元这一档。",{"revision":"opening-2026-11-04"}],[8,"据说两年前重新装修过。厨房约两叠大，墙面贴着壁纸；再往里，是约七叠大小、狭长的木地板房间。朝东的窗户是凸窗，多少有点时髦的样子。",{"revision":"opening-2026-11-04","note":"「２畳」「７畳」是面积大小，不是装修时增加的面积；「ウナギの寝床」形容房间狭长。"}],[9,"（一个月要六万多日元，却只有这样的房间啊。东京的物价果然高。）",{"revision":"opening-2026-11-04"}],[10,"虽然心里有些吃惊，但也觉得，大概就是这么回事吧。",{"revision":"opening-2026-11-04"}],[11,"提前用快递寄来的被褥袋和几个纸箱，零零散散地放在房间里。母亲手脚麻利地开始打扫，我却只是在一旁没来由地晃来晃去。",{"revision":"opening-2026-11-04"}],[12,"那天，我们住进了护城河附近一座安静的会馆。说是供地方公务员使用的福利设施，外观看起来却相当豪华，简直像家城市酒店。",{"revision":"opening-2026-11-04"}],[13,"母亲觉得，公寓里连浴巾都没有，总让人安不下心，第一晚还是住在设施齐全的地方吧。她的判断果然没错：吃完饭、洗过澡，疲惫就一下子涌了上来。",{"revision":"opening-2026-11-04"}],[14,"透过那扇不能开合的大窗，可以看见远处皇居如森林般茂密的绿意。周围，一串串拖着光尾的汽车尾灯，仿佛浮在空中，闪闪发亮。",{"revision":"opening-2026-11-04","note":"「ハメ殺しの窓」指固定、无法开启的窗，不是装了大插销的窗。"}],[15,"我隔着玻璃望着空中流动的灯光，不禁感动地想：东京的夜晚真美啊。我真心觉得，东京的夜晚很漂亮。",{"revision":"opening-2026-11-04"}],[16,"那灯光像春日海面上漂浮的渔船灯火，充满一种寂寞的美。不断传来的车声，听起来也像海浪。我仿佛触碰到了某种令人怀念的东西，久久地站在窗边，望着外面。",{"revision":"opening-2026-11-04"}],[17,"初到东京的第一夜，就是这样度过的。",{"revision":"opening-2026-11-04"}],[18,"第二天起，我们搬进了“英公寓”，做起了从外地来到东京的母子通常都会做的事。也就是说，为了迎接新学期，拼命地大买特买。",{"revision":"opening-2026-11-04"}],[19,"电饭锅、烤面包机、锅、床，各种东西接连送了进来。我们买来现成的窗帘装好，又开着吸尘器，嗡嗡地打扫。",{"revision":"opening-2026-11-04"}],[20,"母亲每天早晨到车站前的银行，用银行卡取出五万、十万日元。我在旁边看着，心里除了感激还是感激。",{"revision":"opening-2026-11-04"}],[21,"总之，在此前十八年的人生里，",{"revision":"opening-2026-11-04"}],[22,"（啊，原来孩子就是花着父母的钱生活的啊。）",{"revision":"opening-2026-11-04"}],[23,"像这样深切地体会到这一点，我还是头一回。",{"revision":"opening-2026-11-04"}],[24,"我父母都是公务员，家里倒也不算太拮据。不过，我还有个小两岁的弟弟。想到接下来几年两个儿子的教育费用，哪怕离车站要走十五分钟、房子已有十三年，也已经该谢天谢地了。",{"revision":"opening-2026-11-04","note":"「ふたつ年下の弟」是一个小两岁的弟弟，不是两个弟弟。"}],[25,"“这段时间，真是让您费心了。”",{"revision":"opening-2026-11-04"}],[26,"母亲明天就要回高知了。那天晚上，我在薄薄的木地板上端正跪坐，轻轻低下头向她道谢。",{"revision":"opening-2026-11-04"}],[27,"想起来，这也是我第一次用郑重的敬体语气向父母道谢。",{"revision":"opening-2026-11-04"}],[28,"“唉，一下子花掉这么多钱，连花钱也会花累呢。”",{"revision":"opening-2026-11-04"}],[29,"母亲的脸上隐约带着疲惫，露出了有些寂寞的微笑。",{"revision":"opening-2026-11-04"}],[30,"短短这几天，七七八八加起来，三十张一万日元的钞票肯定已经花出去了，所以母亲的话里也带着切身的感受。我也“姆哈哈”地干笑了一下。",{"revision":"opening-2026-11-04"}],[31,"母亲环视了一圈房间，",{"revision":"opening-2026-11-04"}],[32,"“东西置办到这个程度，日常生活也就不会有什么不方便了吧。要是想搬到更好的地方，或者买更好的家具，剩下的就自己来吧。玩也好，做什么也好，都随你。不过，每个月给你寄的生活费就是十二万日元。余下的，就靠你自己了。”",{"revision":"opening-2026-11-04"}],[33,"她说话的口气，简直像是在叮嘱刚入职的年轻公务员。",{"revision":"opening-2026-11-04"}],[34,"“嗯。我会打工，也会好好享受生活的。”",{"revision":"opening-2026-11-04"}],[35,"我笑着回答。",{"revision":"opening-2026-11-04"}],[36,"虽说有不少事情还不习惯，不过，能自由自在地过日子，总归是件好事。",{"revision":"opening-2026-11-04"}],[37,"开学前还闲着，不如打打工，先攒点“活动经费”。我兴冲冲地想着这些，那晚睡得很香。",{"revision":"opening-2026-11-04","note":"「軍資金」在这里是开玩笑地说供自己活动、玩乐的钱，不是真的军费。"}],[38,"第二天下午，我独自坐在床边，茫然不知所措。",{"revision":"opening-2026-11-04"}],[39,"睡了个懒觉，起来才发现，母亲已经一个人回去了。",{"revision":"opening-2026-11-04"}],[40,"母亲说要搭一早的第一班飞机回去，我本来打算去送她。可这个能干的母亲就这么把熟睡的儿子留在屋里，只留下三张写得密密麻麻的注意事项，人已经走了。",{"revision":"opening-2026-11-04","note":"搭早班飞机回去的是母亲；拓原本打算送她，而不是陪她一起飞回家。"}],[41,"母亲不是那种舍不得离开儿子的人，这倒省心；可被独自留下的儿子却犯了难。一个人待着，才发现自己简直陷入了——",{"revision":"opening-2026-11-04"}],[42,"（这是哪儿？我是谁？）",{"revision":"opening-2026-11-04"}],[43,"这么一种状况。",{"revision":"opening-2026-11-04"}],[44,"我甚至连自己住的公寓在东京什么位置都不知道。我知道的地方，只有羽田、池袋和石神井公园。",{"revision":"opening-2026-11-04"}],[45,"没办法，为了熟悉这一带的方位，还是买张地图吧。我把一张一万日元的钞票塞进口袋，去了车站前的书店。",{"revision":"opening-2026-11-04"}],[46,"这是独自留下后，我第一次出门逛这条街。街区不大，学生很多，似乎挺适合生活。吃饭的店特别显眼，我居然还冒出了“至少营养方面不用担心了”这种怪念头。",{"revision":"opening-2026-11-04"}],[47,"似乎不少学生趁春假回老家去了，书店里的人比想象中少。我从摆满地图的书架上，取了一本东京都内的地图。",{"revision":"opening-2026-11-04"}],[48,"我把地图递到收银台，一个看上去像是打工大学生的男店员瞥了我一眼，说：",{"revision":"opening-2026-11-04"}],[49,"“买这本吧，用着方便。”",{"revision":"opening-2026-11-04"}],[50,"他麻利地从收银台旁那一摞《ぴあ地图》中拿了一本，装进纸袋，敲起了收银机。",{"revision":"opening-2026-11-04","note":"把地图放进纸袋、操作收银机的人是店员。ぴあ是书刊品牌，不是人名。"}],[51,"一瞬间，",{"revision":"opening-2026-11-04"}],[52,"（啊，我不要那种东西。）",{"revision":"opening-2026-11-04"}],[53,"我差点这么说出口。不过，在这附近住着、打工的大学生，说不定就是同一所大学、同一个学部的学长。我转念一想，还是先老实点吧。事实证明，这么做是对的：后来我才知道，他果然是同校的学长。",{"revision":"opening-2026-11-04"}],[54,"“谢谢。”",{"revision":"opening-2026-11-04","note":"这里的「どうも」承接下句「礼をいって」，表示道谢，不是打招呼。"}],[55,"道过谢后，我去附近的便利店买了锅烧乌冬面食材套装和面包，回到公寓，一直仔细研究地图到傍晚，好让自己熟悉各处的方位。",{"revision":"opening-2026-11-04"}],[56,"说到底，东京就是把许许多多像我长大的那座海滨城市一样大小的城镇，汇集起来形成的巨大集合体。",{"revision":"opening-2026-11-04"}],[57,"在我长大的高知市，商务区、政府办公区、商业街、高级住宅区，连码头都好好地容纳在同一座城里。而东京呢，这些功能分散在一个个不同的街区，街区又彼此连着，仿佛还在不断增生。",{"revision":"opening-2026-11-04"}],[58,"光从地图上看，这里既有河，又有海，还有山嘛。",{"revision":"opening-2026-11-04"}],[59,"有这些就够了。我正这么想着，刚装好的电话便“铃铃铃”地响了起来。",{"revision":"opening-2026-11-04","note":"「とりつけたばかりの電話」是刚安装的家用电话。后文有受话器，不是手机。"}],[60,"当时是傍晚，差一点到六点。",{"revision":"opening-2026-11-04","note":"「６時すこし前」是六点前一点，不是六点多。"}],[61,"母亲搭一早的飞机回去，下午到市政府上班，再从单位回家——时间正好对得上。",{"revision":"opening-2026-11-04"}],[62,"“喂，是杜崎拓吗？”",{"revision":"opening-2026-11-04"}],[63,"我以为是母亲打来的，拿起听筒，听到的却是一个故作斯文、有些不自然的男声。",{"revision":"opening-2026-11-04"}],[64,"一瞬间，我还觉得有点不安：谁会知道这里的电话号码？可紧接着，熟悉的土佐方言就传了过来，我一下子便听出了是谁。",{"revision":"opening-2026-11-04"}],[65,"“拓？是拓吧？我啊，是我！山尾啊——”",{"revision":"opening-2026-11-04"}],[66,"“朝潮啊？”",{"revision":"opening-2026-11-04"}],[67,"打电话来的，是我以前的同班同学山尾忠志。",{"revision":"opening-2026-11-04"}],[68,"山尾的外号叫“朝潮”，因为他胖乎乎的体形，很像家乡引以为傲的相扑力士朝潮。这个外号取得随便得近乎可笑，可又实在贴切。",{"revision":"opening-2026-11-04","note":"「アサシオ」是相扑力士“朝潮”的名字，也用作山尾的外号；「関取」是相扑称谓。"}],[69,"“你怎么知道这里的号码？”",{"revision":"opening-2026-11-04"}],[70,"“笨蛋，问你妈的啊。我想你也差不多该来东京了，这四五天一直猛打你家的电话。刚刚阿姨接了，我就问到了这个号码。可想你了啊，拓——！”",{"revision":"opening-2026-11-04"}],[71,"“喂，怎么回事？想家啦？”",{"revision":"opening-2026-11-04"}],[72,"我坐在床上，把听筒贴紧耳朵，声音也轻快了起来。毕竟，我也很想念他。电话那头，朝潮猛地吸了口气，",{"revision":"opening-2026-11-04"}],[73,"“嗯，我好寂寞啊。拓——！”",{"revision":"opening-2026-11-04"}],[74,"他又拖着一副可怜巴巴、近乎演戏的腔调嚷了起来。大概是太想念老朋友了，满口都是家乡话。",{"revision":"opening-2026-11-04"}],[75,"朝潮——也就是山尾——似乎认定我也已经想家想得不行，立刻打开了话匣子，滔滔不绝地说起来。",{"revision":"opening-2026-11-04"}],[76,"“录取一确定，我妈就乐疯了。她自己想出来玩，二月底就带我来了。结果这里冷得要命，我还感冒了。我躺在床上难受得直哼哼，她倒好，一个人又去歌舞伎座，又逛街买东西，到处玩。后来家里老太太来电话，说我爸带着那个——就是那个漂亮护士——打高尔夫去了。她气得发了一通脾气，就回去了。我都快哭了。你想想，一个人病倒在空荡荡的房间里，真会觉得日子没意思啊。连个认识的人都没有。”",{"revision":"opening-2026-11-04","note":"山尾在抱怨：自己感冒卧床，母亲出去玩，后来因父亲带护士打高尔夫而生气回家。「寒いの寒くないの」在此强调非常冷。「ババア」是对家中老太太的粗鲁称呼，原句未明确是哪一方祖母。"}],[77,"“这我能理解。”",{"revision":"opening-2026-11-04"}],[78,"“所以啊，实在没办法，我就打电话向河村诉苦，求他给我介绍了一个我们大学的学长，可是啊——”",{"revision":"opening-2026-11-04"}],[79,"“你怎么一有点事就往高知打电话啊？”",{"revision":"opening-2026-11-04"}],[80,"我听得直无奈，语气里不知不觉带上了责备。",{"revision":"opening-2026-11-04"}],[81,"河村是我们在高知读高中时，六年级的班主任。我并不怎么喜欢他。",{"revision":"opening-2026-11-04","note":"原文第 181、184 句说明学校采用初高中六年一贯制：四、五、六年级分别相当于高一、高二、高三。这里的六年级不是小学六年级。"}],[82,"如今总算顺顺当当地成了大学生，高中时那些怨气，也早已远在山的那边、天的尽头了。不过，一想起来还是觉得讨厌的人里，他肯定算一个。",{"revision":"opening-2026-11-04"}],[83,"“别跟河村那种家伙诉苦啊。”",{"revision":"opening-2026-11-04"}],[84,"“可这也是没办法的事嘛。你知道我来这儿以后，最先买的是什么吗？”",{"revision":"opening-2026-11-04"}],[85,"“东京地图吧。”",{"revision":"opening-2026-11-04"}],[86,"我故作若无其事地答道，电话那头顿时沉默了一下。",{"revision":"opening-2026-11-04"}],[87,"“你怎么知道的？”",{"revision":"opening-2026-11-04"}],[88,"朝潮说，听起来真是又惊讶又佩服。",{"revision":"opening-2026-11-04"}],[89,"“对啊。我来这儿以后，你也知道，我爸被打高尔夫时认识的那个混账房地产公司老板一通忽悠，买了套二手公寓。我一下飞机，就从羽田打车直接过去了。哪儿是哪儿，根本搞不清。来了以后又躺了半个月。那地方叫涩谷的神泉，可是啊——”",{"revision":"opening-2026-11-04"}],[90,"“那地方，该不会是黄金地段吧？”",{"revision":"opening-2026-11-04"}],[91,"我回想起刚才在书店买来、仔细研究过的东京地图。神泉，不就是几乎挨着山手线圈内的地方吗？确实是黄金地段啊。",{"revision":"opening-2026-11-04"}],[92,"“说来说去，你家还不是当医生赚翻了。我可不想听这种话，越听心情越灰暗。别再打电话来了，从今天起咱们就是陌生人了。”",{"revision":"opening-2026-11-04"}],[93,"我哈哈大笑着，半开玩笑地故意说得很绝。不过，马上就后悔了。",{"revision":"opening-2026-11-04"}],[94,"对着一个身体虚弱、情绪敏感的家伙，可不能随口乱说。电话那头，朝潮像是受了打击，一下子不吭声了，",{"revision":"opening-2026-11-04"}],[95,"“拓，你倒是精神得很嘛……”",{"revision":"opening-2026-11-04"}],[96,"随后传来他带着埋怨、快哭出来的声音。他似乎真的受伤了。我正慌着想补救两句，朝潮却有些恼火地说：",{"revision":"opening-2026-11-04"}],[97,"“果然是那么回事吧？你跟里伽子联系上了，所以才这么来劲吧？可恶！她本来就是这儿的人嘛。你就是这样吧，正高兴得忘乎所以呢吧？有了女人，连哥们儿的情谊都不要了，混蛋！”",{"revision":"opening-2026-11-04","note":"山尾用昵称「リカちゃん」称呼里伽子。这里是他猜测拓已与里伽子联系上，并不是山尾自己联系上了她。"}],[98,"“这怎么又扯到武藤里伽子身上了？”",{"revision":"opening-2026-11-04"}],[99,"我小心翼翼地问着，心却不由得怦怦跳了几下。",{"revision":"opening-2026-11-04"}],[100,"人的名字，真是不可思议。",{"revision":"opening-2026-11-04"}],[101,"毕业典礼前后忙忙乱乱，早被我抛在脑后的高中教室、暮色中的操场、骑自行车上学的路，甚至当时清爽的海风气息，都在一瞬间轰地涌了回来。心里一下子酸楚得不行。",{"revision":"opening-2026-11-04"}],[102,"“她不是考上本地那所正经的国立大学——高知大学了吗？会一直留在那边吧。”",{"revision":"opening-2026-11-04"}],[103,"“你说什么呢，拓？咦，这么说，你还不知道？”",{"revision":"opening-2026-11-04"}],[104,"朝潮本性直率，听起来并不是故意挖苦或讽刺我，而是纯粹感到吃惊。",{"revision":"opening-2026-11-04"}],[105,"“里伽子啊，顾着她妈那边，表面上报考了高知大学，背地里却早就跟在东京的爸爸串通好了。国立大学考完后，她说什么要跟朋友去毕业旅行，就来了东京，原来是来考这边的大学。她什么都瞒着她妈，趁毕业典礼后一团忙乱，嗖地就跑到这边来了。”",{"revision":"opening-2026-11-04","note":"「母親の手前」是顾及母亲、在母亲面前做个交代；「ツーツー」在此指私下彼此通气。"}],[106,"“这是真的？”",{"revision":"opening-2026-11-04"}],[107,"“当然。我一个人寂寞嘛，天天往高知打电话。留在那边的家伙们也闲着，就使劲跟我说我们走了以后发生的新鲜事。这事是跟里伽子很要好的小浜说的，准没错。我一个星期前就听说了。拓，你没听说啊？”",{"revision":"opening-2026-11-04"}],[108,"“没听说。”",{"revision":"opening-2026-11-04"}],[109,"“那你来东京之前，都干什么去了啊？”",{"revision":"opening-2026-11-04"}],[110,"我垂下头，一句话也说不出来。",{"revision":"opening-2026-11-04"}],[111,"因为就要去东京了，这半个多月来，我天天跟留在高知的朋友们出去玩，迪厅、居酒屋、卡拉OK包厢，四处惜别，从没在半夜十二点以前回过家。",{"revision":"opening-2026-11-04","note":"这是回忆来东京前的半个多月，不是抵达东京后的生活。"}],[112,"一起出去玩的，大致总是那几个人，怎么也碰不上跟里伽子要好的小浜她们那群女生。所以，这种消息根本不可能传到我耳朵里。",{"revision":"opening-2026-11-04","note":"「メンツ」在此指一起出去玩的人员、班底，不是他们的外貌；小浜是同学的姓。"}],[113,"是啊，来东京以前，我也不是完全没想过联系里伽子。好吧，说实话，我确实闪过要不要跟她联系一下的念头。",{"revision":"opening-2026-11-04"}],[114,"可真要联系，也该是里伽子先来联系我，才合情理吧。",{"revision":"opening-2026-11-04","note":"「スジ」是道理、合乎情理的次序，不是人名。拓认为该由里伽子先联系他。"}],[115,"我最后一次跟里伽子说话，记得是在学园祭的最后一天——也就是去年的十一月四日。那时，里伽子狠狠扇了我一巴掌，末了还骂道：",{"revision":"opening-2026-11-04"}],[116,"“笨蛋，你这个人差劲透了！”",{"revision":"opening-2026-11-04"}],[117,"骂完，她又斩钉截铁地说，连话都不想跟我说。",{"revision":"opening-2026-11-04"}],[118,"从那以后，我们就没再说过话。说到底，我俩的关系根本不是朝潮想象的那样。我们压根儿就不是那种关系。",{"revision":"opening-2026-11-04"}],[119,"所以，即使是终于要动身去东京的前一晚，我当然也没有给她打电话。",{"revision":"opening-2026-11-04"}],[120,"从高知机场出发时，留在本地的老同学中，有四个女生和三个男生来送我。",{"revision":"opening-2026-11-04"}],[121,"先是一个女生哭了起来，连带着男生们也沉默伤感起来。我也有些不好意思，便随口说些“暑假回来时开个同学会吧”之类的话，嘿嘿笑着，目光四处游移。",{"revision":"opening-2026-11-04"}],[122,"我也顺势隔着门，漫不经心地朝出租车候车处望了望——却没有里伽子的身影。这是当然的，她怎么可能来送我呢。",{"revision":"opening-2026-11-04"}],[123,"我们都要上大学了，我在东京，里伽子在高知，距离又那么远。我认定，这回真的就到此为止了啊，然后走过了检票口。",{"revision":"opening-2026-11-04","note":"「物理的な距離」指东京与高知相隔很远；「これきり」是“到此为止”，不是“这是唯一一次见面”。"}],[124,"在那之后，我想，自己就把里伽子的事忘了。",{"revision":"opening-2026-11-04"}],[125,"我完全没想到，那时候里伽子已经来东京了。",{"revision":"opening-2026-11-04"}],[126,"原来如此，原来是这么回事。最初的震惊慢慢平复下来，我也渐渐觉得有些好笑。",{"revision":"opening-2026-11-04"}],[127,"原来里伽子又是这样，自顾自地把事情办成了啊。",{"revision":"opening-2026-11-04"}],[128,"“喂，拓啊，你在听吗？振作点嘛。”",{"revision":"opening-2026-11-04"}],[129,"电话那头，朝潮仿佛忽然恢复了精神，大声嚷嚷起来。",{"revision":"opening-2026-11-04"}],[130,"“过不了多久，里伽子就会联系你的。说不定她就是追着你，才来这边的呢。”",{"revision":"opening-2026-11-04"}],[131,"“你想得倒真轻松啊。”",{"revision":"opening-2026-11-04"}],[132,"我忍不住扑哧笑了。随后，我突然对朝潮说的话没了兴趣，连自己都觉得有点薄情，可也没办法。我把话题转到些无关紧要的事情上，又聊了十来分钟，约好近期见面，便挂了电话。",{"revision":"opening-2026-11-04","note":"「自分でも薄情やなー」是拓觉得自己薄情，不是在指责山尾。"}],[133,"我往床上一躺，呆呆地出神。过了一会儿，忽然想到什么，就起身把一直塞在壁橱里的旅行包拽出来，取出了我们的毕业生通讯录。",{"revision":"opening-2026-11-04"}],[134,"毕业时，大家决定成立同学会东京分会，我被推去当第一任联络负责人，所以也就被交付了一份通讯录。",{"revision":"opening-2026-11-04"}],[135,"我查出小浜祐实在高知家里的号码，拿起听筒，按下号码。很快，她母亲就接了电话。",{"revision":"opening-2026-11-04"}],[136,"“哎呀，是杜崎同学？怎么样，还好吗？什么时候去东京呀？”",{"revision":"opening-2026-11-04"}],[137,"这反应，可真够悠闲的。",{"revision":"opening-2026-11-04"}],[138,"我吞吞吐吐地说，自己已经到东京了，这通电话也是从东京打来的，想跟小浜聊聊同学会的事——她却说，小浜前天就已经动身去神户了。",{"revision":"opening-2026-11-04","note":"说“小浜前天去了神户”的是她母亲；「おととい」是前天。"}],[139,"直到这时，我才知道，那个脸蛋圆圆的、像白面包一样柔软的可爱的小浜祐实，去了神户的一所女子大学。",{"revision":"opening-2026-11-04"}],[140,"我问了她在神户的联系方式，按下挂断键，心里不免有些惆怅：还真像是到了一个小小的离别季啊。",{"revision":"opening-2026-11-04"}],[141,"四国的高中生啊，想想还真有点奇怪。留在本地的一拨，去京都、大阪、神户的一拨，去东京及关东地区的一拨，就这样散到了日本各地。也就北海道和冲绳算是例外，可即便如此，每年还是会有一两个怪人，真就跑去北海道大学或琉球大学。",{"revision":"opening-2026-11-04"}],[142,"我小心翼翼地，正要按下刚问到的小浜住处的电话号码——",{"revision":"opening-2026-11-04"}],[143,"却不知为什么又改变了主意，把听筒放了回去。事到如今，就算给小浜打电话，打听里伽子的事，又能怎么样呢。",{"revision":"opening-2026-11-04"}],[144,"这才突然发觉肚子饿了，我把买来的锅烧乌冬面套装放到燃气灶上。",{"revision":"opening-2026-11-04"}],[145,"等乌冬面煮好的时候，我漫无目的地看着摊在地板上的地图。回过神来，才发现自己正在找“成城”这个地方。",{"revision":"opening-2026-11-04"}],[146,"那是里伽子的父亲住的地方。既然里伽子来东京了，果然还是住在她爸爸的公寓里吧。",{"revision":"opening-2026-11-04"}],[147,"“成城”这个地名很快就找到了，可也仅此而已。我既不知道详细地址，也不知道电话号码。",{"revision":"opening-2026-11-04"}],[148,"乌冬面煮开了，我起身去关火，目光却忽然停在地板上的一点。那里掉着一张照片。",{"revision":"opening-2026-11-04"}],[149,"那是将近一年前，五年级修学旅行时，四班的须田在威基基海滩偷拍的里伽子的照片。旅行结束后，男生之间传看过一本秘密相册，这张照片就是其中最受欢迎的一张。",{"revision":"opening-2026-11-04","note":"五年级相当于高二，见第 181、184 句的学制说明。这里说的是秘密相册里最受欢迎的一张照片。"}],[150,"她穿着白底黑圆点的泳衣。泳衣本身很普通，里伽子的身材却出人意料地丰满——也就是所谓的身材好，在男生中很是引起了一番议论。",{"revision":"opening-2026-11-04"}],[151,"要说身材好，一班的泽田美惠和五班的樱庭久美子也在其列，不过，她们穿着校服时，就已经看得出来了。",{"revision":"opening-2026-11-04"}],[152,"可是里伽子穿着校服时明明显得清瘦苗条，一换上泳衣，身材却丰满得让人大吃一惊，因此格外引人注目，那张照片也卖得特别好。",{"revision":"opening-2026-11-04"}],[153,"（这种照片，怎么会在这儿？）",{"revision":"opening-2026-11-04"}],[154,"我捡起照片看着，出了一会儿神。大概是从旅行包里拿通讯录的时候，原本夹在什么东西里的照片掉出来了吧。",{"revision":"opening-2026-11-04"}],[155,"照片里的里伽子看上去很不高兴。她抱着膝盖，呆呆地望着那片明信片一般湛蓝的海。",{"revision":"opening-2026-11-04","note":"抱着膝盖望海的人是照片里的里伽子，不是正在看照片的拓。"}],[156,"明明才一月底，夏威夷的海却蓝得澄澈透亮，简直像合成照片一样，没有真实感。",{"revision":"opening-2026-11-04"}],[157,"可唯独照片里里伽子那张不知为何心事重重的脸，是真实的。",{"revision":"opening-2026-11-04"}],[158,"并没有用长焦镜头，却能把里伽子拍得这么近，是因为须田那家伙为了这一天，早就通过杂志邮购了一架内置照相机的双筒望远镜。他装模作样地拿望远镜看远处的海，实际上却对着穿泳衣的女生们，一个接一个地咔嚓咔嚓偷拍。",{"revision":"opening-2026-11-04"}],[159,"我拿里伽子的照片“下饭”，吸溜着乌冬面，忽然想起修学旅行时，在下榻酒店的大堂被里伽子叫住的那一幕。",{"revision":"opening-2026-11-04","note":"「オカズ」在此借用“下饭菜”的说法，写拓一边看照片一边吃乌冬面；原文没有另外添蔬菜。"}],[160,"那一次，可以说是我头一回正经跟里伽子说话。",{"revision":"opening-2026-11-04"}],[161,"如今想来，那件事实在很有象征意味。",{"revision":"opening-2026-11-04"}],[162,"里伽子找我说话，是因为有明确的目的，并不是出于什么恋爱——也就是说，不是因为喜欢我之类的。",{"revision":"opening-2026-11-04"}],[163,"她并不喜欢我，压根儿没有那回事——直到现在，我才真切地体会到这一点。忽然间，我预感到，自己恐怕再也见不到里伽子了。",{"revision":"opening-2026-11-04","note":"“她不喜欢我”是拓此时的理解，不是叙述者已经证实的里伽子的心意。省略的主语是里伽子，并非“我不喜欢她”。"}],[164,"明知道从这个春天起，我们就住在同一座城市里——虽说是个大都市——里伽子却没有跟我有过任何联系。",{"revision":"opening-2026-11-04","note":"结合上下文，知道两人会同住东京却未联系对方的，是里伽子。这是拓从她未联系自己而展开的推想。"}],[165,"要说里伽子是因为难为情、害羞才不联系我，那根本不可能。",{"revision":"opening-2026-11-04"}],[166,"没有联系，说到底，就是她没有联系我的打算。",{"revision":"opening-2026-11-04","note":"省略的主语承接前文，是里伽子没有联系拓的打算，不是拓不想联系她。"}],[167,"在不看地图就连哪儿是哪儿都搞不清的东京，想跟里伽子偶然重逢，简直就像寻找掉在沙滩上的一颗小钻石。是啊，偶然重逢这种事，基本上是不可能的。",{"revision":"opening-2026-11-04"}],[168,"看着照片里的里伽子，几个有她在场的片段又浮现在了脑海里。",{"revision":"opening-2026-11-04"}],[169,"升上六年级后分到同一个班的事，黄金周的那次短途旅行，两个人一起住过的酒店，还有许多许多事情。",{"revision":"opening-2026-11-04","note":"六年级相当于高三，并非小学六年级。这里回想的是此前两人共同经历的片段。"}],[170,"那些让我觉得挺开心、或是感到惊讶的事，对里伽子来说，原来都没有什么意义啊。",{"revision":"opening-2026-11-04","note":"这是拓当时带着失落作出的推断，不表示里伽子亲口说过这些经历毫无意义。"}],[171,"这么一想，心里多少有些寂寞。",{"revision":"opening-2026-11-04"}],[172,"那时，我才第一次意识到，原来自己那么喜欢里伽子，心里随即涌上一股仿佛再也无法挽回的悲伤。",{"revision":"opening-2026-11-04"}]]){
 window.CURATED[index]={...window.CURATED[index],zh,translationReview};
}
